//! Runtime support for code generated by the imping modding suite.
//!
//! Generated bindings depend on this crate and nothing else. It provides:
//!
//! - [`Module`]: a module's expected identity. [`Module::init`] finds the
//!   module in the running process and checks it is the build the bindings
//!   were generated from, then resolves addresses relative to its base.
//! - [`Global`]: a typed global variable at an address in a module, read and
//!   written safely when its type is [`Plain`] data.
//! - [`Hook`]: the guard returned by a generated function's `hook`, which
//!   enables, disables and (on drop) disables the hook.
//! - Strings in the target's memory: [`CStrPtr`] and [`WStrPtr`] for `char*`
//!   and `wchar_t*`, [`CStrBuf`] and [`WStrBuf`] for fixed-size buffers in
//!   structs, and [`WString`] to pass UTF-16 text to the target.
//! - Base classes: [`Inherits`] records that a class derives from another, and
//!   [`Upcast::upcast`] turns a pointer to a class into a pointer to a base.
//! - [`Error`]: everything that can go wrong.
//!
//! [`Module`], [`Global`] and the string types are also usable on their own,
//! without generated code.
//!
//! # Example
//!
//! ```no_run
//! use imping_runtime::{Global, Module};
//!
//! static GAME: Module = Module::new("game.exe", 0x64b8f2a1, 0xa2b000);
//! static GRAVITY: Global<f32> = Global::new(&GAME, 0x3a1200);
//!
//! fn main() -> imping_runtime::Result<()> {
//!     // SAFETY: `game.exe` with this timestamp and image size keeps an `f32`
//!     // at RVA 0x3a1200.
//!     unsafe { GAME.init() }?;
//!     GRAVITY.write(4.9);
//!     Ok(())
//! }
//! ```
//!
//! # What stays `unsafe`
//!
//! A module's `init` is the one promise that the bindings describe the running
//! build; with it made, plain globals, hooks, forwarding a hooked call and
//! functions marked safe need no further `unsafe`. What stays `unsafe` depends
//! on the target's state at run time, which only the caller can know:
//! dereferencing a pointer the target handed out, reading a string through
//! one, and calling a function that is not marked safe.
//!
//! Dereference once per block rather than once per access:
//!
//! ```no_run
//! # #[repr(C)] struct Entity { health: f32, armor: f32 }
//! # let player: *mut Entity = std::ptr::null_mut();
//! // SAFETY: `player` is null or points to a live entity owned by the target.
//! if let Some(player) = unsafe { player.as_mut() } {
//!     player.health = 100.0;
//!     player.armor = 50.0;
//! }
//! ```
//!
//! # Unloading
//!
//! Hooks jump into code in the mod that installed them. Before a mod's DLL is
//! unloaded, drop (or disable) every [`Hook`] it holds. A hook kept with
//! [`Hook::leak`] means the mod must never be unloaded.
//!
//! # Platforms
//!
//! Windows only for now. On other platforms the crate compiles, but
//! [`Module::init`] returns [`Error::UnsupportedPlatform`].

mod backend;
mod error;
mod global;
mod hook;
mod inherits;
mod module;
mod plain;
mod strings;
mod sys;

pub use crate::error::{Error, Result};
pub use crate::global::Global;
pub use crate::hook::Hook;
pub use crate::inherits::{Inherits, Upcast};
pub use crate::module::Module;
pub use crate::plain::Plain;
pub use crate::strings::{CStrBuf, CStrPtr, WStrBuf, WStrPtr, WString};

/// Plumbing for code generated by `imping-codegen`. Not a supported API: it
/// changes in step with the generator.
#[doc(hidden)]
pub mod __private {
    pub use crate::hook::{Slot, install};
}
